import app from './worker-v135.js';
import { PROFESSIONAL_SCHEMA_V136 } from './professional-schema-v136.js';

const HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
const AVAILABILITY=new Set(['AVAILABLE','LIMITED','UNAVAILABLE','PAUSED']);
const LOCATION_MODES=new Set(['REMOTE','LOCAL','HYBRID']);
const CAPABILITY_CATEGORIES=new Set(['DESIGN','DEVELOPMENT','WRITING','TRANSLATION','MARKETING','PHOTO_VIDEO','AUDIO','CONSULTING','EDUCATION','HOME_SERVICE','REPAIR','INSTALLATION','CREATIVE','ADMIN','OTHER']);
const PROPOSAL_STATUSES=new Set(['DRAFT','SENT','VIEWED','ACCEPTED','DECLINED','WITHDRAWN','COUNTERED']);
const PROJECT_STATUSES=new Set(['NOT_STARTED','ACTIVE','WAITING','REVIEW','COMPLETED','CANCELLED','DISPUTED']);
const MILESTONE_STATUSES=new Set(['PENDING','IN_PROGRESS','SUBMITTED','APPROVED','REVISION_REQUESTED','COMPLETED','CANCELLED']);
const RESTRICTED_CAPABILITY_TERMS=['weapon','explosive','illegal drug','medical diagnosis','legal representation','investment guarantee','adult service'];
const now=()=>new Date().toISOString();
const uid=prefix=>`${prefix}${crypto.randomUUID().replaceAll('-','')}`;
const publicId=prefix=>`${prefix}-${crypto.randomUUID().replaceAll('-','').slice(0,16).toUpperCase()}`;
const clean=(value,max=5000)=>String(value??'').replace(/\0/g,'').trim().slice(0,max);
const normalized=value=>clean(value,5000).toLocaleLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const key=value=>normalized(value).replaceAll(' ','_').slice(0,100);
const json=(value,status=200,headers={})=>new Response(JSON.stringify(value),{status,headers:{...HEADERS,...headers}});
const safeJson=(value,fallback={})=>{try{return JSON.parse(value||'')}catch{return fallback}};
const list=(value,max=30,itemMax=180)=>[...new Set((Array.isArray(value)?value:[]).map(item=>clean(item,itemMax)).filter(Boolean))].slice(0,max);
const bool=value=>value===true||value===1||value==='1';
const int=(value,min,max)=>{const number=Number(value);return Number.isInteger(number)&&number>=min&&number<=max?number:null};
const cents=value=>value===null||value===undefined||value===''?null:int(value,0,1_000_000_000);
const currency=value=>/^[A-Z]{3}$/.test(clean(value,3).toUpperCase())?clean(value,3).toUpperCase():'EUR';
const safeDate=value=>{const input=clean(value,10);if(!input)return null;if(!/^\d{4}-\d{2}-\d{2}$/.test(input))return null;const date=new Date(`${input}T00:00:00Z`);return Number.isNaN(date.valueOf())||date.toISOString().slice(0,10)!==input?null:input};
const safeUrl=value=>{try{const url=new URL(clean(value,1000));return url.protocol==='https:'?url.href:null}catch{return null}};
function log(event,fields={}){console.log(JSON.stringify({scope:'still_professional',event,at:now(),...fields}))}
async function sha(value){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value)));return[...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('')}
function cookie(request,name){for(const part of(request.headers.get('cookie')||'').split(';')){const[k,...value]=part.trim().split('=');if(k===name)return decodeURIComponent(value.join('='))}return''}
async function buyerSession(request,env){const token=cookie(request,'still_buyer');if(!token||!env.DB)return null;return env.DB.prepare(`SELECT a.id buyer_account_id,a.email,a.name,a.email_verified FROM buyer_sessions s JOIN buyer_accounts a ON a.id=s.buyer_account_id WHERE s.token_hash=? AND s.expires_at>? AND a.status='active'`).bind(await sha(token),now()).first()}
function sameOrigin(request){const origin=request.headers.get('origin');return!origin||origin===new URL(request.url).origin}
function rewrite(request,pathname){const url=new URL(request.url);url.pathname=pathname;url.search='';return new Request(url,{method:'GET',headers:request.headers})}
let schemaReady;
async function ensureSchema(env){
  if(!schemaReady)schemaReady=(async()=>{
    await env.DB.batch(PROFESSIONAL_SCHEMA_V136.map(sql=>env.DB.prepare(sql)));
    for(const column of ['professional_id TEXT','professional_project_id TEXT']){
      try{await env.DB.prepare(`ALTER TABLE world_resolution_outcomes ADD COLUMN ${column}`).run()}catch(error){if(!/duplicate column|already exists/i.test(error?.message||''))throw error}
    }
    await env.DB.prepare(`INSERT OR IGNORE INTO professional_fee_config(id,basis_points,fixed_fee_cents,updated_at) VALUES('active',0,0,?)`).bind(now()).run();
  })().catch(error=>{schemaReady=undefined;throw error});
  await schemaReady;
}
function historyStatement(env,buyerId,entityType,entityId,eventType,title,details={},sourceType='professional',sourceId=null){const ts=now();return env.DB.prepare(`INSERT INTO world_history_events(id,public_id,buyer_account_id,entity_type,entity_public_id,event_type,title,details_json,source_type,source_public_id,occurred_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('whe_'),publicId('HIS'),buyerId,entityType,entityId,eventType,clean(title,180),JSON.stringify(details).slice(0,4000),sourceType,sourceId,ts,ts)}
function notificationStatement(env,buyerId,sourceKey,type,title,body,href){return env.DB.prepare(`INSERT OR IGNORE INTO professional_notifications(id,public_id,buyer_account_id,source_key,notification_type,title,body,href,created_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('pno_'),publicId('NTF'),buyerId,sourceKey,type,clean(title,180),clean(body,500)||null,clean(href,500),now())}
function projectEventStatement(env,projectId,actorId,type,title,details={}){return env.DB.prepare(`INSERT INTO professional_project_events(id,public_id,project_id,actor_buyer_account_id,event_type,title,details_json,created_at) VALUES(?,?,?,?,?,?,?,?)`).bind(uid('pev_'),publicId('EVT'),projectId,actorId,type,clean(title,180),JSON.stringify(details).slice(0,4000),now())}
async function blockExists(env,a,b){if(!a||!b)return false;const row=await env.DB.prepare(`SELECT 1 ok FROM market_blocks WHERE (blocker_buyer_account_id=? AND blocked_buyer_account_id=?) OR (blocker_buyer_account_id=? AND blocked_buyer_account_id=?) LIMIT 1`).bind(a,b,b,a).first();return!!row}
async function profileByBuyer(env,buyerId){return env.DB.prepare(`SELECT p.*,a.email,a.name account_name,a.email_verified FROM professional_profiles p JOIN buyer_accounts a ON a.id=p.buyer_account_id WHERE p.buyer_account_id=?`).bind(buyerId).first()}
async function profileByPublicId(env,id){return env.DB.prepare(`SELECT p.*,a.email_verified FROM professional_profiles p JOIN buyer_accounts a ON a.id=p.buyer_account_id WHERE p.public_id=?`).bind(id).first()}
function profileJson(row,{privateView=false}={}){if(!row)return null;return{publicId:row.public_id,professionalModeEnabled:!!row.professional_mode_enabled,displayName:row.display_name,headline:row.headline||null,bio:row.bio||null,coarseLocation:row.coarse_location||null,locationModes:safeJson(row.location_modes_json,[]),availabilityStatus:row.availability_status,weeklyCapacityHours:row.weekly_capacity_hours,minimumProjectCents:row.minimum_project_cents,currency:row.currency,profileStatus:row.profile_status,emailVerified:!!row.email_verified,...(privateView?{email:row.email||null}:{}),createdAt:row.created_at,updatedAt:row.updated_at}}
function capabilityJson(row){return{publicId:row.public_id,key:row.capability_key,name:row.label,category:row.category,level:row.level||null,description:row.description||null,yearsExperience:row.years_experience,sourceType:row.source_type,verificationStatus:row.verification_status,evidenceCount:Number(row.evidence_count||0),createdAt:row.created_at,updatedAt:row.updated_at}}
async function capabilitiesFor(env,profileId){const rows=await env.DB.prepare(`SELECT c.*,(SELECT COUNT(*) FROM professional_capability_evidence e WHERE e.capability_id=c.id) evidence_count FROM professional_capabilities c WHERE c.profile_id=? ORDER BY c.label`).bind(profileId).all();return(rows.results||[]).map(capabilityJson)}

function profileInput(body,current,buyer){
  const displayName=clean(body.displayName??current?.display_name??buyer.name,120);
  const availability=clean(body.availabilityStatus??current?.availability_status??'UNAVAILABLE',20).toUpperCase();
  const modes=list(body.locationModes??safeJson(current?.location_modes_json,[]),3,20).map(x=>x.toUpperCase()).filter(x=>LOCATION_MODES.has(x));
  const status=bool(body.professionalModeEnabled??current?.professional_mode_enabled)&&displayName.length>=2?'ACTIVE':'DRAFT';
  return{displayName,enabled:bool(body.professionalModeEnabled??current?.professional_mode_enabled),headline:clean(body.headline??current?.headline,180)||null,bio:clean(body.bio??current?.bio,1500)||null,location:clean(body.coarseLocation??current?.coarse_location,120)||null,modes,availability:AVAILABILITY.has(availability)?availability:'UNAVAILABLE',capacity:int(body.weeklyCapacityHours??current?.weekly_capacity_hours,1,168),minimum:cents(body.minimumProjectCents??current?.minimum_project_cents),currency:currency(body.currency??current?.currency),status};
}
async function saveProfile(request,env,buyer){const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const current=await profileByBuyer(env,buyer.buyer_account_id),input=profileInput(body,current,buyer);if(input.displayName.length<2)return json({error:'display_name_required'},422);if(input.enabled&&!input.modes.length)return json({error:'location_mode_required'},422);const ts=now();if(current)await env.DB.prepare(`UPDATE professional_profiles SET professional_mode_enabled=?,display_name=?,headline=?,bio=?,coarse_location=?,location_modes_json=?,availability_status=?,weekly_capacity_hours=?,minimum_project_cents=?,currency=?,profile_status=?,updated_at=? WHERE buyer_account_id=?`).bind(input.enabled?1:0,input.displayName,input.headline,input.bio,input.location,JSON.stringify(input.modes),input.availability,input.capacity,input.minimum,input.currency,input.status,ts,buyer.buyer_account_id).run();else await env.DB.prepare(`INSERT INTO professional_profiles(id,public_id,buyer_account_id,professional_mode_enabled,display_name,headline,bio,coarse_location,location_modes_json,availability_status,weekly_capacity_hours,minimum_project_cents,currency,profile_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('prf_'),publicId('PRO'),buyer.buyer_account_id,input.enabled?1:0,input.displayName,input.headline,input.bio,input.location,JSON.stringify(input.modes),input.availability,input.capacity,input.minimum,input.currency,input.status,ts,ts).run();log(input.enabled&&!current?.professional_mode_enabled?'professional_mode_enabled':'professional_profile_saved',{buyerId:buyer.buyer_account_id});const saved=await profileByBuyer(env,buyer.buyer_account_id);return json({ok:true,profile:profileJson(saved,{privateView:true}),capabilities:await capabilitiesFor(env,saved.id)},current?200:201)}
async function addCapability(request,env,buyer){const profile=await profileByBuyer(env,buyer.buyer_account_id);if(!profile?.professional_mode_enabled)return json({error:'professional_mode_required'},409);const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const name=clean(body.name,120),capKey=key(body.key||name),category=clean(body.category,30).toUpperCase();if(name.length<2||!capKey)return json({error:'capability_name_required'},422);if(!CAPABILITY_CATEGORIES.has(category))return json({error:'unsupported_capability_category'},422);if(RESTRICTED_CAPABILITY_TERMS.some(term=>normalized(`${name} ${body.description}`).includes(term)))return json({error:'restricted_professional_category'},422);const ts=now(),existing=await env.DB.prepare(`SELECT id FROM professional_capabilities WHERE profile_id=? AND capability_key=?`).bind(profile.id,capKey).first();if(existing)return json({error:'capability_exists'},409);await env.DB.prepare(`INSERT INTO professional_capabilities(id,public_id,profile_id,capability_key,label,category,level,description,years_experience,source_type,verification_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'USER_DECLARED','UNVERIFIED',?,?)`).bind(uid('pca_'),publicId('CAP'),profile.id,capKey,name,category,clean(body.level,40)||null,clean(body.description,800)||null,int(body.yearsExperience,0,80),ts,ts).run();log('capability_added',{buyerId:buyer.buyer_account_id,capabilityKey:capKey,verificationStatus:'UNVERIFIED'});return json({ok:true,capabilities:await capabilitiesFor(env,profile.id)},201)}
async function addPortfolio(request,env,buyer){const profile=await profileByBuyer(env,buyer.buyer_account_id);if(!profile?.professional_mode_enabled)return json({error:'professional_mode_required'},409);const body=await request.json().catch(()=>null),title=clean(body?.title,180);if(title.length<2)return json({error:'title_required'},422);let documentId=null;if(body.documentId){const document=await env.DB.prepare(`SELECT id FROM world_documents WHERE buyer_account_id=? AND public_id=? AND archived_at IS NULL`).bind(buyer.buyer_account_id,clean(body.documentId,40)).first();if(!document)return json({error:'document_not_found'},404);documentId=document.id}const external=clean(body.externalUrl)?safeUrl(body.externalUrl):null;if(clean(body.externalUrl)&&!external)return json({error:'external_url_must_be_https'},422);const capabilityKeys=list(body.capabilityKeys,20,100).map(key),capabilities=capabilityKeys.length?(await env.DB.prepare(`SELECT * FROM professional_capabilities WHERE profile_id=?`).bind(profile.id).all()).results.filter(capability=>capabilityKeys.includes(capability.capability_key)):[];if(capabilityKeys.length!==capabilities.length)return json({error:'portfolio_capability_not_found'},404);const ts=now(),internal=uid('ppi_'),pid=publicId('POR'),statements=[env.DB.prepare(`INSERT INTO professional_portfolio_items(id,public_id,profile_id,title,description,external_url,document_id,capability_keys_json,is_public,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(internal,pid,profile.id,title,clean(body.description,2000)||null,external,documentId,JSON.stringify(capabilityKeys),body.isPublic===false?0:1,ts,ts)];for(const capability of capabilities)statements.push(env.DB.prepare(`INSERT OR IGNORE INTO professional_capability_evidence(id,public_id,capability_id,evidence_type,source_type,source_public_id,title,description,created_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('pce_'),publicId('EVD'),capability.id,'WORK_SAMPLE','PORTFOLIO',pid,title,clean(body.description,1200)||null,ts));await env.DB.batch(statements);return json({ok:true,portfolioId:pid},201)}

