const PROJECT_SELECT=`SELECT p.*,d.public_id deal_public_id,d.status deal_status,d.amount_cents,d.currency,d.payment_mode,d.payment_status,d.platform_fee_cents,pr.public_id proposal_public_id,pr.summary proposal_summary,pr.scope proposal_scope,b.public_id brief_public_id,b.title brief_title,b.objective,b.scope brief_scope,b.deliverables_json brief_deliverables,b.requirements_json brief_constraints,n.public_id need_public_id,n.required_capabilities_json,ca.name client_name,pa.name professional_name,pp.public_id professional_public_id FROM professional_projects p JOIN professional_deals d ON d.id=p.deal_id JOIN professional_proposals pr ON pr.id=d.proposal_id JOIN professional_briefs b ON b.id=p.brief_id JOIN world_needs n ON n.id=p.need_id JOIN buyer_accounts ca ON ca.id=p.client_buyer_account_id JOIN buyer_accounts pa ON pa.id=p.professional_buyer_account_id JOIN professional_profiles pp ON pp.buyer_account_id=p.professional_buyer_account_id`;
