async function workBootstrap(env,buyer){const profile=await profileByBuyer(env,buyer.buyer_account_id),[opportunities,projects,proposals,notifications]=await Promise.all([env.DB.prepare(`SELECT o.public_id,o.status,o.match_score,o.shared_at,b.title,b.deadline FROM professional_opportunities o JOIN professional_briefs b ON b.id=o.brief_id WHERE o.professional_buyer_account_id=? ORDER BY o.updated_at DESC LIMIT 100`).bind(buyer.buyer_account_id).all(),env.DB.prepare(`SELECT p.public_id,p.title,p.status,p.due_at,p.completed_at,CASE WHEN p.client_buyer_account_id=? THEN 'CLIENT' ELSE 'PROFESSIONAL' END viewer_role FROM professional_projects p WHERE p.client_buyer_account_id=? OR p.professional_buyer_account_id=? ORDER BY p.updated_at DESC LIMIT 100`).bind(buyer.buyer_account_id,buyer.buyer_account_id,buyer.buyer_account_id).all(),env.DB.prepare(`SELECT p.public_id,p.status,p.amount_cents,p.currency,p.updated_at,o.public_id opportunity_public_id,b.title FROM professional_proposals p JOIN professional_opportunities o ON o.id=p.opportunity_id JOIN professional_briefs b ON b.id=o.brief_id WHERE p.client_buyer_account_id=? OR p.professional_buyer_account_id=? ORDER BY p.updated_at DESC LIMIT 100`).bind(buyer.buyer_account_id,buyer.buyer_account_id).all(),env.DB.prepare(`SELECT public_id,notification_type,title,body,href,read_at,created_at FROM professional_notifications WHERE buyer_account_id=? ORDER BY created_at DESC LIMIT 100`).bind(buyer.buyer_account_id).all()]);return{profile:profile?profileJson(profile,{privateView:true}):null,capabilities:profile?await capabilitiesFor(env,profile.id):[],opportunities:opportunities.results||[],projects:projects.results||[],proposals:proposals.results||[],notifications:notifications.results||[],paymentCapability:{mode:'EXTERNAL_MANUAL',providerConfigured:false,escrow:false,notice:'Payment is handled outside Still unless a real provider is connected.'}}}
async function augmentNow(request,env,ctx,buyer){const response=await app.fetch(request,env,ctx);if(!response.ok)return response;const data=await response.json(),work=await workBootstrap(env,buyer),actionable=work.notifications.filter(item=>!item.read_at).slice(0,8),active=work.projects.filter(item=>!['COMPLETED','CANCELLED'].includes(item.status));return json({...data,professional:{enabled:!!work.profile?.professionalModeEnabled,availabilityStatus:work.profile?.availabilityStatus||'UNAVAILABLE',notifications:actionable,activeProjects:active.slice(0,6),opportunities:work.opportunities.filter(item=>['SUGGESTED','VIEWED','INTERESTED'].includes(item.status)).slice(0,6)},quietState:Boolean(data.quietState)&&!actionable.length&&!active.length})}

async function handleApi(request,env,ctx,buyer,url){const path=url.pathname;let match;if(path==='/api/v1/professional/profile'){if(request.method==='GET'){const profile=await profileByBuyer(env,buyer.buyer_account_id);return json({profile:profileJson(profile,{privateView:true}),capabilities:profile?await capabilitiesFor(env,profile.id):[]})}if(['POST','PATCH'].includes(request.method))return saveProfile(request,env,buyer)}if(path==='/api/v1/professional/capabilities'){if(request.method==='GET'){const profile=await profileByBuyer(env,buyer.buyer_account_id);return json({capabilities:profile?await capabilitiesFor(env,profile.id):[]})}if(request.method==='POST')return addCapability(request,env,buyer)}if(path==='/api/v1/professional/portfolio'&&request.method==='POST')return addPortfolio(request,env,buyer);if(path==='/api/v1/professional/portfolio'&&request.method==='GET'){const profile=await profileByBuyer(env,buyer.buyer_account_id);if(!profile)return json({portfolio:[]});const rows=await env.DB.prepare(`SELECT public_id,title,description,external_url,capability_keys_json,is_public,created_at,updated_at FROM professional_portfolio_items WHERE profile_id=? ORDER BY updated_at DESC`).bind(profile.id).all();return json({portfolio:(rows.results||[]).map(row=>({...row,capabilityKeys:safeJson(row.capability_keys_json,[])}))})}match=path.match(/^\/api\/v1\/professional\/profiles\/([^/]+)$/);if(match&&request.method==='GET'){const profile=await profileByPublicId(env,decodeURIComponent(match[1]));if(!profile?.professional_mode_enabled||profile.profile_status!=='ACTIVE')return json({error:'not_found'},404);const feedback=await env.DB.prepare(`SELECT COUNT(*) completed_projects,AVG(outcome_rating) outcome,AVG(communication_rating) communication,AVG(reliability_rating) reliability FROM professional_feedback WHERE professional_buyer_account_id=?`).bind(profile.buyer_account_id).first(),portfolio=await env.DB.prepare(`SELECT public_id,title,description,external_url,capability_keys_json FROM professional_portfolio_items WHERE profile_id=? AND is_public=1 ORDER BY updated_at DESC LIMIT 20`).bind(profile.id).all();return json({profile:profileJson(profile),capabilities:await capabilitiesFor(env,profile.id),completedWork:{count:Number(feedback?.completed_projects||0),structuredAverages:Number(feedback?.completed_projects||0)?{outcome:Number(feedback.outcome),communication:Number(feedback.communication),reliability:Number(feedback.reliability)}:null},portfolio:portfolio.results||[]})}if(path==='/api/v1/professional/work'&&request.method==='GET')return json(await workBootstrap(env,buyer));if(path==='/api/v1/professional/proposals'&&request.method==='POST')return createProposal(request,env,buyer);match=path.match(/^\/api\/v1\/professional\/proposals\/([^/]+)$/);if(match&&request.method==='GET'){const row=await proposalForParticipant(env,decodeURIComponent(match[1]),buyer.buyer_account_id);return row?json({proposal:await proposalJson(env,row)}):json({error:'not_found'},404)}if(match&&request.method==='PATCH')return updateProposal(request,env,buyer,decodeURIComponent(match[1]));match=path.match(/^\/api\/v1\/professional\/opportunities\/([^/]+)$/);if(match&&request.method==='GET')return readOpportunity(env,buyer,decodeURIComponent(match[1]));match=path.match(/^\/api\/v1\/professional\/opportunities\/([^/]+)\/interest$/);if(match&&request.method==='POST')return opportunityAction(request,env,buyer,decodeURIComponent(match[1]));match=path.match(/^\/api\/v1\/professional\/opportunities\/([^/]+)\/documents\/([^/]+)\/file$/);if(match&&request.method==='GET')return opportunityFile(request,env,buyer,decodeURIComponent(match[1]),decodeURIComponent(match[2]));match=path.match(/^\/api\/v1\/professional\/projects\/([^/]+)$/);if(match&&request.method==='GET'){const project=await projectForParticipant(env,decodeURIComponent(match[1]),buyer.buyer_account_id);return project?json({project:await projectPayload(env,project,buyer.buyer_account_id)}):json({error:'not_found'},404)}match=path.match(/^\/api\/v1\/professional\/projects\/([^/]+)\/milestones$/);if(match&&request.method==='POST')return createMilestone(request,env,buyer,decodeURIComponent(match[1]));match=path.match(/^\/api\/v1\/professional\/projects\/([^/]+)\/messages$/);if(match&&request.method==='POST')return projectMessage(request,env,buyer,decodeURIComponent(match[1]));match=path.match(/^\/api\/v1\/professional\/projects\/([^/]+)\/(complete|cancel|dispute|feedback|favorite)$/);if(match&&request.method==='POST'){const id=decodeURIComponent(match[1]);if(match[2]==='complete')return completeProject(request,env,buyer,id);if(match[2]==='cancel')return cancelProject(request,env,buyer,id);if(match[2]==='dispute')return openDispute(request,env,buyer,id);if(match[2]==='feedback')return createFeedback(request,env,buyer,id);return favoriteProfessional(env,buyer,id)}match=path.match(/^\/api\/v1\/professional\/milestones\/([^/]+)\/(submit|approve|revision)$/);if(match&&request.method==='POST'){const id=decodeURIComponent(match[1]);return match[2]==='submit'?submitMilestone(request,env,buyer,id):match[2]==='approve'?approveMilestone(env,buyer,id):reviseMilestone(request,env,buyer,id)}match=path.match(/^\/api\/v1\/professional\/deliverables\/([^/]+)\/file$/);if(match&&request.method==='GET')return deliverableFile(env,buyer,decodeURIComponent(match[1]));if(path==='/api/v1/professional/reports'&&request.method==='POST')return safetyReport(request,env,buyer);if(path==='/api/v1/professional/blocks'&&request.method==='POST')return blockProfessional(request,env,buyer);match=path.match(/^\/api\/v1\/professional\/notifications\/([^/]+)\/read$/);if(match&&request.method==='POST'){await env.DB.prepare(`UPDATE professional_notifications SET read_at=COALESCE(read_at,?) WHERE public_id=? AND buyer_account_id=?`).bind(now(),decodeURIComponent(match[1]),buyer.buyer_account_id).run();return json({ok:true})}match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/brief$/);if(match&&request.method==='GET'){const need=await needForOwner(env,buyer.buyer_account_id,decodeURIComponent(match[1]));if(!need)return json({error:'need_not_found'},404);const brief=await briefForNeed(env,buyer.buyer_account_id,need.id);return json({brief:brief?briefJson(brief,await briefAttachments(env,brief.id)):null})}if(match&&request.method==='POST')return saveBrief(request,env,buyer,decodeURIComponent(match[1]));match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/brief\/share$/);if(match&&request.method==='POST')return shareBrief(request,env,buyer,decodeURIComponent(match[1]));match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/professional-matches$/);if(match&&request.method==='GET')return getMatches(env,buyer,decodeURIComponent(match[1]),url);return json({error:'not_found'},404)}

let foundationReady=false;
export default{async fetch(request,env,ctx){const url=new URL(request.url),path=url.pathname,isProfessional=path.startsWith('/api/v1/professional/')||/^\/api\/v1\/world\/needs\/[^/]+\/(brief|professional-matches)/.test(path),nowRoute=path==='/api/v1/world/now'&&request.method==='GET';if(!isProfessional&&!nowRoute)return app.fetch(request,env,ctx);try{const buyer=await buyerSession(request,env);if(!buyer)return json({error:'unauthorized'},401);if(!['GET','HEAD'].includes(request.method)&&!sameOrigin(request))return json({error:'origin_not_allowed'},403);if(!foundationReady){const warm=await app.fetch(rewrite(request,'/api/v1/world/needs'),env,ctx);if(!warm.ok)return warm;foundationReady=true}await ensureSchema(env);if(nowRoute)return augmentNow(request,env,ctx,buyer);return handleApi(request,env,ctx,buyer,url)}catch(error){log('professional_request_failed',{path,category:clean(error?.name||'error',80),message:clean(error?.message,240)});return json({error:error?.message||'professional_network_unavailable'},error?.status>=400&&error?.status<600?error.status:500)}}};
